//! `PrimitiveCollection` membership, reference counting, events, errors and
//! destruction against the pinned CesiumJS traces in
//! `tests/data/scene-primitive-collection.json` (generated by
//! `tools/cesium/generate-scene-primitive-collection.mjs`).

use cesium_rs::core::*;
use cesium_rs::renderer::UniformFrame;
use cesium_rs::scene::*;
use serde_json::{json, Value};
use std::collections::HashMap;
use std::sync::{Arc, Mutex};

type Log = Arc<Mutex<Vec<Value>>>;

const DESTROYED: &str = "This object was destroyed, i.e., destroy() was called.";

/// Behaves like an object passed through Cesium's `destroyObject`: after
/// `destroy`, every method fails.
struct Fake {
    name: String,
    log: Log,
    destroyed: bool,
}

impl Fake {
    fn live(&self) -> Result<(), RuntimeError> {
        if self.destroyed {
            Err(RuntimeError::new(DESTROYED))
        } else {
            Ok(())
        }
    }
}

impl ScenePrimitive for Fake {
    fn pre_passes_update(&mut self, _: &mut FrameState) -> Result<(), RuntimeError> {
        self.live()
    }
    fn update(&mut self, _: &mut FrameState) -> Result<(), RuntimeError> {
        self.live()?;
        self.log.lock().unwrap().push(json!(["update", self.name]));
        Ok(())
    }
    fn post_passes_update(&mut self, _: &mut FrameState) -> Result<(), RuntimeError> {
        self.live()
    }
    fn update_for_pass(&mut self, _: &mut FrameState, _: Cesium3DTilePass) -> Result<(), RuntimeError> {
        self.live()
    }
    fn destroy(&mut self) -> Result<(), RuntimeError> {
        self.live()?;
        self.log.lock().unwrap().push(json!(["destroy", self.name]));
        self.destroyed = true;
        Ok(())
    }
}

fn frame() -> FrameState {
    let mut camera = Camera::new(CameraOptions::new(16., 16.));
    let uniform = camera.uniform_camera();
    let culling = camera.frustum.compute_culling_volume(uniform.position, uniform.direction, uniform.up);
    FrameState::new(UniformFrame::new(uniform, JulianDate::new(2451545., 0., TimeStandard::Tai)), culling, [16, 16])
}

#[test]
fn membership_counting_events_and_destruction_match_reference() {
    let fixture: Value = serde_json::from_str(include_str!("data/scene-primitive-collection.json")).unwrap();
    let mut frame = frame();
    let mut steps_checked = 0;
    for scenario in fixture["scenarios"].as_array().unwrap() {
        let name = scenario["name"].as_str().unwrap();
        let log: Log = Arc::default();
        let names: Arc<Mutex<HashMap<u64, String>>> = Arc::default();
        let mut collections: Vec<PrimitiveCollection> = scenario["collections"]
            .as_array()
            .unwrap()
            .iter()
            .enumerate()
            .map(|(i, o)| {
                let mut c = PrimitiveCollection::new(PrimitiveCollectionOptions {
                    show: o["show"].as_bool(),
                    destroy_primitives: o["destroyPrimitives"].as_bool(),
                    count_references: o["countReferences"].as_bool(),
                });
                let (l, n) = (log.clone(), names.clone());
                c.primitive_added.add_event_listener(move |p| {
                    let name = n.lock().unwrap()[&p.id()].clone();
                    l.lock().unwrap().push(json!(["added", i, name]));
                });
                let (l, n) = (log.clone(), names.clone());
                c.primitive_removed.add_event_listener(move |p| {
                    let name = n.lock().unwrap()[&p.id()].clone();
                    l.lock().unwrap().push(json!(["removed", i, name]));
                });
                c
            })
            .collect();
        let mut primitives: Vec<(String, PrimitiveHandle)> = Vec::new();

        for (i, step) in scenario["steps"].as_array().unwrap().iter().enumerate() {
            let op = step["op"].as_str().unwrap();
            let c = step["collection"].as_u64().unwrap() as usize;
            let mut handle = |arg: &str| {
                if let Some((_, h)) = primitives.iter().find(|(n, _)| n == arg) {
                    return h.clone();
                }
                let h = PrimitiveHandle::new(Fake { name: arg.into(), log: log.clone(), destroyed: false });
                names.lock().unwrap().insert(h.id(), arg.into());
                primitives.push((arg.into(), h.clone()));
                h
            };
            let before = log.lock().unwrap().len();
            let arg = &step["arg"];
            let index = step["index"].as_u64().map(|v| v as usize);
            let outcome: Result<Value, RuntimeError> = match op {
                "add" => {
                    let h = handle(arg.as_str().unwrap());
                    collections[c].add(h, index).map(|p| json!(names.lock().unwrap()[&p.id()]))
                }
                "remove" => {
                    let h = handle(arg.as_str().unwrap());
                    collections[c].remove(&h).map(Value::from)
                }
                "removeAndDestroy" => {
                    let h = handle(arg.as_str().unwrap());
                    collections[c].remove_and_destroy(&h).map(Value::from)
                }
                "removeAll" => collections[c].remove_all().map(|_| Value::Null),
                "raise" | "raiseToTop" | "lower" | "lowerToBottom" => {
                    let h = handle(arg.as_str().unwrap());
                    let col = &mut collections[c];
                    match op {
                        "raise" => col.raise(&h),
                        "raiseToTop" => col.raise_to_top(&h),
                        "lower" => col.lower(&h),
                        _ => col.lower_to_bottom(&h),
                    }
                    .map(|_| Value::Null)
                }
                "get" => Ok(collections[c]
                    .get(arg.as_u64().unwrap() as usize)
                    .map_or(Value::Null, |p| json!(names.lock().unwrap()[&p.id()]))),
                "update" => collections[c].update(&mut frame).map(|_| Value::Null),
                "destroy" => collections[c].destroy().map(|_| Value::Null),
                other => panic!("unknown op {other}"),
            };
            let context = format!("{name} step {i} {op} {arg}");
            let (result, error) = match outcome {
                Ok(v) => (v, Value::Null),
                Err(e) => (Value::Null, json!(e.message)),
            };
            assert_eq!(result, step["result"], "{context} result");
            assert_eq!(error, step["error"], "{context} error");
            assert_eq!(log.lock().unwrap()[before..].to_vec(), *step["events"].as_array().unwrap(), "{context} events");

            for (ci, col) in collections.iter().enumerate() {
                assert_eq!(json!(col.is_destroyed()), step["destroyed"][ci], "{context} destroyed {ci}");
                if col.is_destroyed() {
                    continue;
                }
                let order: Vec<String> =
                    (0..col.length()).map(|k| names.lock().unwrap()[&col.get(k).unwrap().id()].clone()).collect();
                assert_eq!(json!(order), step["order"][ci], "{context} order {ci}");
                for (n, h) in &primitives {
                    assert_eq!(json!(col.contains(h)), step["contains"][ci][n], "{context} contains {n} in {ci}");
                }
            }
            for (n, h) in &primitives {
                assert_eq!(json!(h.reference_count()), step["referenceCounts"][n], "{context} count {n}");
            }
            steps_checked += 1;
        }
    }
    assert_eq!(steps_checked, 59);
}

/// Handles that wrap the same primitive allocation share its identity,
/// memberships and reference count, as Cesium's `_external` record lives on
/// the primitive object itself.
#[test]
fn handles_wrapping_one_allocation_share_membership() {
    let log: Log = Arc::default();
    let shared: std::rc::Rc<std::cell::RefCell<dyn ScenePrimitive>> =
        std::rc::Rc::new(std::cell::RefCell::new(Fake { name: "a".into(), log: log.clone(), destroyed: false }));
    let first = PrimitiveHandle::from_rc(shared.clone());
    let second = PrimitiveHandle::from_rc(shared.clone());
    assert!(first.ptr_eq(&second));
    assert_eq!(first.id(), second.id());

    let counting = PrimitiveCollectionOptions { count_references: Some(true), ..Default::default() };
    let mut c0 = PrimitiveCollection::new(counting);
    let mut c1 = PrimitiveCollection::new(counting);
    c0.add(first.clone(), None).unwrap();
    c1.add(second.clone(), None).unwrap();
    assert_eq!(first.reference_count(), Some(2));
    assert!(c0.contains(&second), "a second handle is recognized");

    assert!(c0.remove(&second).unwrap(), "remove accepts either handle");
    assert!(log.lock().unwrap().is_empty(), "the other collection still holds the primitive");
    assert_eq!(second.reference_count(), Some(1));
    assert!(c1.remove(&first).unwrap());
    assert_eq!(*log.lock().unwrap(), vec![json!(["destroy", "a"])]);

    // A different allocation is a different primitive.
    let other = PrimitiveHandle::new(Fake { name: "b".into(), log, destroyed: false });
    assert!(!other.ptr_eq(&first));
    assert_ne!(other.id(), first.id());
}
